    const ns = {} as StreamersNamespace;
    ns.list = () =>
      handle(buildUrl(this.baseUrl, "/streamers/live"), () =>
        this.api.GET("/streamers/live", {}),
      );
    ns.live = (onData, onError) =>
      subscribeStreamersLive(this.baseUrl, onData, onError);
